import SwiftUI
import SwiftData
import MapKit

struct DayDetailView: View {
    @Environment(\.modelContext) private var context; @Bindable var day:TravelDay
    @State private var filter:ActivityPeriod?=nil;@State private var editor=false;@State private var editing:ItineraryActivity?;@State private var showMap=false
    var visible:[ItineraryActivity]{day.sortedActivities.filter{filter == nil || $0.period == filter}}
    var body:some View{
        ZStack(alignment:.bottomTrailing){Pastel.background.ignoresSafeArea();ScrollView{VStack(alignment:.leading,spacing:18){
            HStack{VStack(alignment:.leading,spacing:4){Text("D\(day.dayNumber) · \(day.date.formatted(.dateTime.month().day()))").font(.largeTitle.bold()).foregroundStyle(Pastel.text);Text(day.date.chineseWeekday).foregroundStyle(Pastel.secondary)};Spacer();Image("pigCamera").resizable().scaledToFit().frame(width:86,height:86)}
            ScrollView(.horizontal,showsIndicators:false){HStack{FilterChip(title:"全部",selected:filter==nil){filter=nil};ForEach(ActivityPeriod.allCases){p in FilterChip(title:p.rawValue,selected:filter==p){filter=p}}}}
            HStack{SectionHeader(title:"今日安排",subtitle:"\(visible.count) 项");Button{showMap=true}label:{Label("地图",systemImage:"map").font(.caption.weight(.semibold))}}
            if visible.isEmpty{EmptyStateView(image:"pigEmpty",title:"这段时间还空着",message:"加一个想去的地方，给今天一点期待。",buttonTitle:"添加安排",action:{editing=nil;editor=true})}
            ForEach(visible){activity in ActivityCard(activity:activity){activity.isCompleted.toggle();try? context.save()}.contentShape(Rectangle()).onTapGesture{editing=activity;editor=true}.contextMenu{if let coordinate=activity.coordinate{Button{openInMaps(activity,coordinate:coordinate)}label:{Label("在 Apple 地图中打开",systemImage:"map")}};Button{move(activity,offset:-1)}label:{Label("向前移动",systemImage:"arrow.up")};Button{move(activity,offset:1)}label:{Label("向后移动",systemImage:"arrow.down")};Button(role:.destructive){day.activities.removeAll{$0.id==activity.id};context.delete(activity);try? context.save()}label:{Label("删除",systemImage:"trash")}}}
        }.frame(maxWidth:1000).frame(maxWidth:.infinity).padding(18).padding(.bottom,70)};RoundedIconButton(icon:"plus",color:Pastel.yellow){editing=nil;editor=true}.padding(22)}
        .navigationTitle("每日行程").navigationBarTitleDisplayMode(.inline).sheet(isPresented:$editor){NavigationStack{ActivityEditorView(day:day,activity:editing)}}.sheet(isPresented:$showMap){NavigationStack{DayMapView(day:day)}}
    }
    private func move(_ activity:ItineraryActivity,offset:Int){let ordered=day.sortedActivities;guard let index=ordered.firstIndex(where:{$0.id==activity.id})else{return};let target=max(0,min(ordered.count-1,index+offset));guard target != index else{return};let other=ordered[target],old=activity.orderIndex;activity.orderIndex=other.orderIndex;other.orderIndex=old;try? context.save()}
    private func openInMaps(_ activity:ItineraryActivity,coordinate:CLLocationCoordinate2D){let item=MKMapItem(placemark:MKPlacemark(coordinate:coordinate));item.name=activity.title;item.openInMaps()}
}
struct FilterChip:View{let title:String;let selected:Bool;let action:()->Void;var body:some View{Button(action:action){Text(title).font(.subheadline.weight(.semibold)).foregroundStyle(Pastel.text).padding(.horizontal,16).padding(.vertical,9).background(selected ? Pastel.yellow : .white).clipShape(Capsule()).overlay(Capsule().stroke(Pastel.text.opacity(0.08)))}.buttonStyle(.plain)}}

struct ActivityEditorView:View{
    @Environment(\.dismiss)private var dismiss;@Environment(\.modelContext)private var context
    let day:TravelDay;var activity:ItineraryActivity?
    @State private var title="";@State private var start=Date.now;@State private var end=Date.now.addingTimeInterval(3600);@State private var period=ActivityPeriod.morning;@State private var kind=ActivityKind.sightseeing;@State private var location="";@State private var address="";@State private var notes="";@State private var url="";@State private var cost=0.0;@State private var searchResults:[PlaceResult]=[];@State private var searching=false;@State private var coordinate:CLLocationCoordinate2D?
    var overlaps:Bool{day.activities.contains{$0.id != activity?.id && start < $0.endTime && end > $0.startTime}}
    var body:some View{Form{
        Section{TextField("活动名称",text:$title);Picker("类型",selection:$kind){ForEach(ActivityKind.allCases){Label($0.rawValue,systemImage:$0.icon).tag($0)}};DatePicker("开始",selection:$start,displayedComponents:.hourAndMinute);DatePicker("结束",selection:$end,in:start...,displayedComponents:.hourAndMinute);Picker("时段",selection:$period){ForEach(ActivityPeriod.allCases){Text($0.rawValue).tag($0)}}.pickerStyle(.segmented);if overlaps{Label("与已有安排时间重叠，仍可保存。",systemImage:"exclamationmark.triangle.fill").font(.caption).foregroundStyle(.orange)}}header:{Text("时间与内容")}
        Section{TextField("搜索地点",text:$location);if searching{ProgressView()}else{ForEach(searchResults){place in Button{location=place.name;address=place.subtitle;coordinate=place.coordinate;searchResults=[]}label:{VStack(alignment:.leading){Text(place.name);Text(place.subtitle).font(.caption).foregroundStyle(.secondary)}}}};if !address.isEmpty{Text(address).font(.caption)}}header:{HStack{Text("地点");Spacer();Button("搜索"){Task{await searchPlace()}}}}
        Section{TextField("备注",text:$notes,axis:.vertical).lineLimit(3...6);TextField("网址（可选）",text:$url).keyboardType(.URL);TextField("预计费用",value:$cost,format:.number).keyboardType(.decimalPad)}header:{Text("更多")}
    }.scrollContentBackground(.hidden).background(Pastel.background).navigationTitle(activity==nil ? "添加安排":"编辑安排").navigationBarTitleDisplayMode(.inline).toolbar{ToolbarItem(placement:.cancellationAction){Button("取消"){dismiss()}};ToolbarItem(placement:.confirmationAction){Button("保存",action:save).disabled(title.isEmpty||end<=start)}}.onChange(of:start){_,value in if activity==nil{let hour=Calendar.current.component(.hour,from:value);period=hour<12 ? .morning : (hour<18 ? .afternoon:.evening)}}.onAppear{guard let a=activity else{start=day.date.setting(hour:9,minute:0);end=day.date.setting(hour:10,minute:0);return};title=a.title;start=a.startTime;end=a.endTime;period=a.period;kind=a.kind;location=a.locationName;address=a.address;notes=a.notes;url=a.website;cost=a.estimatedCost;coordinate=a.coordinate}}
    private func searchPlace()async{guard !location.isEmpty else{return};searching=true;defer{searching=false};searchResults=(try? await LocationSearchService().search(location)) ?? []}
    private func save(){let a=activity ?? ItineraryActivity(title:title,startTime:start,endTime:end,period:period,kind:kind,locationName:location,orderIndex:day.activities.count);a.title=title;a.startTime=start;a.endTime=end;a.period=period;a.kind=kind;a.locationName=location;a.address=address;a.notes=notes;a.website=url;a.estimatedCost=cost;a.latitude=coordinate?.latitude;a.longitude=coordinate?.longitude;a.day=day;if activity==nil{day.activities.append(a)};try? context.save();dismiss()}
}

struct DayMapView:View{
    let day:TravelDay;@State private var position:MapCameraPosition = .automatic
    var located:[ItineraryActivity]{day.activities.filter{$0.coordinate != nil}}
    var body:some View{Group{if located.isEmpty{EmptyStateView(image:"pigMap",title:"还没有地图位置",message:"编辑活动并搜索地点后，小桃会把它标在地图上。") }else{Map(position:$position){ForEach(located){a in if let c=a.coordinate{Marker(a.title,coordinate:c).tint(Pastel.peachStrong)}}}.mapControls{MapCompass();MapScaleView();MapUserLocationButton()}}}.navigationTitle("今日地图").navigationBarTitleDisplayMode(.inline)}
}

struct MealPlanView:View{
    @Environment(\.modelContext)private var context;let trip:Trip;@State private var selected:TravelDay?;@State private var editor=false;@State private var editing:Meal?
    var day:TravelDay?{selected ?? trip.sortedDays.first}
    var body:some View{ZStack(alignment:.bottomTrailing){Pastel.background.ignoresSafeArea();ScrollView{VStack(alignment:.leading,spacing:16){ScrollView(.horizontal,showsIndicators:false){HStack{ForEach(trip.sortedDays){d in FilterChip(title:"D\(d.dayNumber)",selected:day?.id==d.id){selected=d}}}};SectionHeader(title:"饮食计划",subtitle:day?.date.formatted(.dateTime.month().day()));if let day,day.meals.isEmpty{EmptyStateView(image:"pigMap",title:"今天吃什么？",message:"把想去的餐厅和预约信息放在这里。",buttonTitle:"添加餐食",action:{editing=nil;editor=true})}else if let day{ForEach(day.meals.sorted{$0.plannedTime<$1.plannedTime}){meal in Button{editing=meal;editor=true}label:{MealCard(meal:meal)}.buttonStyle(.plain).contextMenu{Button(role:.destructive){day.meals.removeAll{$0.id==meal.id};context.delete(meal);try? context.save()}label:{Label("删除",systemImage:"trash")}}}}}.frame(maxWidth:900).frame(maxWidth:.infinity).padding(18).padding(.bottom,70)};RoundedIconButton(icon:"plus",color:Pastel.peach){editing=nil;editor=true}.padding(22)}.navigationTitle("饮食计划").navigationBarTitleDisplayMode(.inline).sheet(isPresented:$editor){if let day{NavigationStack{MealEditorView(day:day,meal:editing)}}}}
}
struct MealEditorView:View{@Environment(\.dismiss)private var dismiss;@Environment(\.modelContext)private var context;let day:TravelDay;var meal:Meal?;@State private var type=MealType.lunch;@State private var name="";@State private var cuisine="";@State private var location="";@State private var time=Date.now;@State private var notes="";@State private var reservation="";@State private var cost=0.0;var body:some View{Form{Section{Picker("餐别",selection:$type){ForEach(MealType.allCases){Text($0.rawValue).tag($0)}};TextField("餐厅名称",text:$name);TextField("菜系",text:$cuisine);DatePicker("时间",selection:$time,displayedComponents:.hourAndMinute)};Section{TextField("地点",text:$location);TextField("预约信息",text:$reservation);TextField("预计费用",value:$cost,format:.number);TextField("备注",text:$notes,axis:.vertical)}}.navigationTitle(meal==nil ? "添加餐食":"编辑餐食").navigationBarTitleDisplayMode(.inline).toolbar{ToolbarItem(placement:.cancellationAction){Button("取消"){dismiss()}};ToolbarItem(placement:.confirmationAction){Button("保存",action:save).disabled(name.isEmpty)}}.onAppear{guard let m=meal else{time=day.date.setting(hour:12,minute:0);return};type=m.type;name=m.restaurantName;cuisine=m.cuisine;location=m.locationName;time=m.plannedTime;notes=m.notes;reservation=m.reservationDetails;cost=m.estimatedCost}};private func save(){let m=meal ?? Meal(type:type,restaurantName:name,plannedTime:time);m.type=type;m.restaurantName=name;m.cuisine=cuisine;m.locationName=location;m.plannedTime=time;m.notes=notes;m.reservationDetails=reservation;m.estimatedCost=cost;m.day=day;if meal==nil{day.meals.append(m)};try? context.save();dismiss()}}

